#define hue(v)  ( .6 + .6 * cos( 6.3*(v)  + vec4(0,23,21,0)  ) )


void mainImage( out vec4 O, vec2 u )
{
    vec2 R = iResolution.xy;
    float v = textureLod(iChannel1, u/iResolution.xy,2.).r,     // source video
          t = 5.*iTime;
    O = v > .5 ? v * hue(iTime) 
               : .99 * T(1.01*(u-R/2.)+R/2. +.5*vec2(sin(t),cos(.87*t)) ); // prev image displaced and scaled
}
